  data.notes.forEach((note) => {
    const noteX = projectX(note.x);
    const noteY = projectY(note.y);

    notesGroup
      .append('text')
      .attr('x', noteX)
      .attr('y', noteY)
      .attr('text-anchor', 'start')
      .attr('font-size', 11)
      .attr('fill', theme.axisTextColor)
      .attr('font-weight', 'bold')
      .text(note.text);

const chartWidth = width - configValues.padding * 2;
